import{_ as r,C as n,o as s,c as i,j as t,a as o,E as c,a2 as p}from"./chunks/framework.BxGh02fV.js";const k=JSON.parse('{"title":"Open a workspace","description":"","frontmatter":{"title":"Open a workspace"},"headers":[],"relativePath":"en/guide/start.md","filePath":"en/guide/start.md"}'),l={name:"en/guide/start.md"};function h(d,e,g,u,f,w){const a=n("Capture");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"open-a-workspace",tabindex:"-1"},[o("Open a workspace "),t("a",{class:"header-anchor",href:"#open-a-workspace","aria-label":'Permalink to "Open a workspace"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("The picker is Effortless's home screen: you land on it at every launch once your profile exists (on the very first launch, see "),t("a",{href:"/Effortless/en/guide/first-run.html"},"First launch"),o("), and whenever you click the grid icon or "),t("strong",null,"+"),o(" in the top bar. A workspace is an Effortless project: you come here to open one, create one or adopt an existing project.")],-1)),c(a,{name:"selecteur",alt:"The workspace picker: actions on the left, recent workspaces on the right"}),e[2]||(e[2]=p('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>At the top</strong>: the title &quot;Open a workspace&quot; and the reminder &quot;A workspace = an Effortless project.&quot;</li><li><strong>On the left</strong>: four actions — <strong>Open…</strong>, <strong>Create…</strong>, <strong>Creation assistant</strong>, <strong>Adopt an existing project</strong> — and a path input.</li><li><strong>On the right</strong>: the <strong>Recent</strong> list, grouped by category once you have declared some (Workshop, Customers, Internal in the example). Each card shows the project name, its path and its &quot;Last opened&quot; date. While the list is empty, the screen shows &quot;No recent workspace. Open or create a project on the left.&quot;</li></ul><p>The tabs, theme and preferences of the top bar are described in <a href="/Effortless/en/guide/window.html">Window, bars and tray</a>.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="open-an-existing-project" tabindex="-1">Open an existing project <a class="header-anchor" href="#open-an-existing-project" aria-label="Permalink to &quot;Open an existing project&quot;">​</a></h3><p>Click <strong>Open…</strong> (&quot;Select an existing project folder&quot;) and choose the folder. You can also type the absolute path in <strong>…or enter an absolute path</strong>, then click <strong>Open</strong>. The project opens in a tab; if it is already open, its tab is reactivated.</p><p>If opening fails, a message starting with &quot;Error:&quot; shows below the actions, with the reason given by the engine (or &quot;Unable to open.&quot;).</p><h3 id="create-a-workspace" tabindex="-1">Create a workspace <a class="header-anchor" href="#create-a-workspace" aria-label="Permalink to &quot;Create a workspace&quot;">​</a></h3><p><strong>Create…</strong> (&quot;Initialize a workspace in a folder&quot;) has you pick a folder, initializes it as an Effortless workspace and opens it at once, with no further question.</p><p><strong>Creation assistant</strong> is a separate button: a guided flow in five steps — project, provider, stack, scaffold, deployment. See <a href="/Effortless/en/guide/create.html">Creation assistant</a>.</p><h3 id="adopt-an-existing-project" tabindex="-1">Adopt an existing project <a class="header-anchor" href="#adopt-an-existing-project" aria-label="Permalink to &quot;Adopt an existing project&quot;">​</a></h3><p><strong>Adopt an existing project</strong> brings a repository already under way (&quot;brownfield&quot;) into Effortless: you pick its folder, then a four-step assistant opens. See <a href="/Effortless/en/guide/adopt.html">Adopt an existing project</a>.</p><h3 id="reopen-a-recent-workspace" tabindex="-1">Reopen a recent workspace <a class="header-anchor" href="#reopen-a-recent-workspace" aria-label="Permalink to &quot;Reopen a recent workspace&quot;">​</a></h3><p>Click a card in the <strong>Recent</strong> list to reopen the workspace. When you hover over a card, controls appear on its right:</p><ul><li>a drop-down list to file the project under a category — only once you have declared at least one category;</li><li><strong>✎</strong> (&quot;Rename (display name)&quot;): the name becomes an editable field. <strong>Save</strong> or Enter confirms, <strong>Cancel</strong> or Escape cancels. If you empty the field, the rename is simply cancelled;</li><li><strong>×</strong> removes the project from the list: &quot;Remove?&quot; asks for confirmation, answer <strong>Yes</strong> or <strong>No</strong>. Nothing is deleted on disk.</li></ul><h3 id="sort-into-categories" tabindex="-1">Sort into categories <a class="header-anchor" href="#sort-into-categories" aria-label="Permalink to &quot;Sort into categories&quot;">​</a></h3><p><strong>Categories</strong> (top right of the list) opens category management:</p><ul><li>type a name in <strong>New category</strong>, then <strong>Add</strong>;</li><li>rename a category by editing its name: the change is saved when you leave the field or press Enter;</li><li>delete it with <strong>Delete category</strong>. Its projects stay in the list, uncategorized.</li></ul><p>If a name is refused, the screen shows &quot;Category not saved (name already taken?).&quot; You file a project under a category with the drop-down list that appears when you hover over its card; without a choice, it sits under &quot;Uncategorized&quot;.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>An agent has no picker: it works in the workspace folder, resolved from its working directory. <code>effortless_init</code> creates a workspace, <code>effortless_status</code> reports its state.</p>',21))])}const y=r(l,[["render",h]]);export{k as __pageData,y as default};
